import logging


class KeyMapper:
    """Maps semantic key names to Samsung TV protocol payloads."""

    def __init__(self, key_interval=1.5):
        self.key_interval = key_interval

    def map_key(self, key, repeat=1):
        """Build a protocol payload for a given key."""
        return {
            'method': 'ms.remote.control',
            'params': {
                'Cmd': 'Click',
                'DataOfCmd': key,
                'Option': 'false',
                'TypeOfRemote': 'SendRemoteKey'
            }
        }

    def send_key(self, websocket, key, repeat=1):
        """Send a key with optional repeat count."""
        for n in range(repeat):
            payload = self.map_key(key)
            logging.info('Sending key %s', key)
            websocket.send(payload)
            if n < repeat - 1:  # Wait only between repeats, not after final one
                import time
                time.sleep(self.key_interval)
